import React, { useState, useEffect } from 'react';
import './GestionJugadores.css';

function GestionJugadores() {
  const [jugadores, setJugadores] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem('token');
    
    fetch('http://localhost:5001/api/jugadores', {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    })
    .then(res => {
      if (!res.ok) throw new Error('Error al cargar');
      return res.json();
    })
    .then(data => {
      console.log('Jugadores cargados:', data);
      setJugadores(data);
      setLoading(false);
    })
    .catch(err => {
      console.error('Error:', err);
      setError(err.message);
      setLoading(false);
    });
  }, []);

  if (loading) {
    return <div className="cargando">Cargando jugadores...</div>;
  }

  if (error) {
    return <div className="error">Error: {error}</div>;
  }

  return (
    <div className="gestion-jugadores">
      <div className="header">
        <h2>🏃 Gestionar Jugadores</h2>
      </div>

      {/* Tarjetas de estadísticas */}
      <div className="stats">
        <div className="stat-card">
          <div className="stat-number">{jugadores.length}</div>
          <div className="stat-label">Total Jugadores</div>
        </div>
        <div className="stat-card">
          <div className="stat-number">{jugadores.filter(j => j.posicion === 'Delantero').length}</div>
          <div className="stat-label">Delanteros</div>
        </div>
        <div className="stat-card">
          <div className="stat-number">{jugadores.filter(j => j.posicion === 'Defensa').length}</div>
          <div className="stat-label">Defensas</div>
        </div>
      </div>

      {/* Tabla */}
      <div className="tabla-wrapper">
        <table className="tabla-jugadores">
          <thead>
            <tr>
              
              <th>Cédula</th>
              <th>Nombre</th>
              <th>Email</th>
              <th>#</th>
              <th>Posición</th>
              <th>Teléfono</th>
            </tr>
          </thead>
          <tbody>
            {jugadores.map(j => (
              <tr key={j.id}>
                
                <td>{j.identificacion}</td>
                <td><strong>{j.nombre}</strong></td>
                <td>{j.email}</td>
                <td className="centro">{j.numero_camiseta || '-'}</td>
                <td className="centro">{j.posicion || '-'}</td>
                <td>{j.telefono || '-'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {jugadores.length === 0 && (
        <div className="sin-datos">
          No hay jugadores registrados
        </div>
      )}
    </div>
  );
}

export default GestionJugadores;
